function [mc] = coil_command(p_j, m_cmd, m_max)
%COIL_COMMAND  A coil's dipole command [A m^2]: its row p_j of the allocation times the body dipole command, saturated at +-m_max.
%   p_j: real[1][3] (passed a plain number)
%   m_cmd: real[1][3] (passed a plain number)
%   m_max: real[1] (passed a plain number)
%   returns mc: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    mc = 0;
    mc = asils.models.coilsat.act_clamp((((p_j(1) * m_cmd(1)) + (p_j(2) * m_cmd(2))) + (p_j(3) * m_cmd(3))), (-(m_max)), m_max);
end
